// از تقویم فارسی داخلی موتور Node.js (Intl، با ICU کامل) استفاده می‌شود تا از
// خطای محاسبه‌ی دستی تاریخ شمسی (به‌خصوص نزدیک نوروز) جلوگیری شود.
// نیازمند Node.js با ICU کامل است (پیش‌فرض نسخه‌های رسمی nodejs.org از v13 به بعد).
const jalaliFormatter = new Intl.DateTimeFormat('fa-IR-u-ca-persian-nu-latn', {
  year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hour12: false
});
function toJalaliString(date) {
  return jalaliFormatter.format(new Date(date));
}

const row = $json;
if (!row || row.error || !row.telegram_chat_id) return [];
const text = 'یادآوری: تیکت ' + row.public_ref + ' (دسته: ' + row.category + ') از ' +
  toJalaliString(row.created_at) + ' بدون پاسخ مانده است.';
return [{ json: { chat_id: row.telegram_chat_id, text: text } }];

// از تقویم فارسی داخلی موتور Node.js (Intl، با ICU کامل) استفاده می‌شود تا از
// خطای محاسبه‌ی دستی تاریخ شمسی (به‌خصوص نزدیک نوروز) جلوگیری شود.
// نیازمند Node.js با ICU کامل است (پیش‌فرض نسخه‌های رسمی nodejs.org از v13 به بعد).
const jalaliFormatter = new Intl.DateTimeFormat('fa-IR-u-ca-persian-nu-latn', {
  year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hour12: false
});
function toJalaliString(date) {
  return jalaliFormatter.format(new Date(date));
}

const ticket = $('یافتن تیکت‌های ۲۴ ساعته بی‌پاسخ').first().json;
const adminRows = $('یافتن چت آیدی مدیر').all();
if (!ticket || ticket.error || !adminRows.length || adminRows[0].json.error || !adminRows[0].json.telegram_chat_id) return [];
const text = 'هشدار: تیکت ' + ticket.public_ref + ' (دسته: ' + ticket.category + ') از ' +
  toJalaliString(ticket.created_at) + ' پس از ۲۴ ساعت هنوز بدون پاسخ است.';
return [{ json: { chat_id: adminRows[0].json.telegram_chat_id, text: text } }];

// از تقویم فارسی داخلی موتور Node.js (Intl، با ICU کامل) استفاده می‌شود تا از
// خطای محاسبه‌ی دستی تاریخ شمسی (به‌خصوص نزدیک نوروز) جلوگیری شود.
// نیازمند Node.js با ICU کامل است (پیش‌فرض نسخه‌های رسمی nodejs.org از v13 به بعد).
const jalaliFormatter = new Intl.DateTimeFormat('fa-IR-u-ca-persian-nu-latn', {
  year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hour12: false
});
function toJalaliString(date) {
  return jalaliFormatter.format(new Date(date));
}

function fmtInterval(pgInterval) {
  if (!pgInterval) return 'نامشخص';
  if (typeof pgInterval === 'string') return pgInterval;
  const h = pgInterval.hours || 0;
  const m = pgInterval.minutes || 0;
  const d = pgInterval.days || 0;
  return (d ? d + ' روز و ' : '') + h + ' ساعت و ' + m + ' دقیقه';
}

const byCat = $('آمار تیکت به تفکیک دسته').all().filter(function (r) { return !r.json.error; }).map(function (r) { return r.json; });
const avgReply = $('میانگین زمان اولین پاسخ هر واحد').all().filter(function (r) { return !r.json.error; }).map(function (r) { return r.json; });
const openRows = $('تعداد تیکت‌های باز').all();
const openCount = (openRows.length && !openRows[0].json.error) ? openRows[0].json.open_count : 'نامشخص';
const topUnanswered = $('پرتکرارترین سؤال‌های بی‌پاسخ').all().filter(function (r) { return !r.json.error; }).map(function (r) { return r.json; });
const adminRows = $('یافتن چت آیدی مدیر برای گزارش').all();

if (!adminRows.length || adminRows[0].json.error || !adminRows[0].json.telegram_chat_id) return [];

const lines = [];
lines.push('گزارش هفتگی — تا ' + toJalaliString(new Date()));
lines.push('');
lines.push('تعداد تیکت به تفکیک دسته:');
if (byCat.length) {
  byCat.forEach(function (r) { lines.push('- ' + r.category + ': ' + r.total); });
} else {
  lines.push('- موردی ثبت نشده است.');
}
lines.push('');
lines.push('میانگین زمان اولین پاسخ هر واحد:');
if (avgReply.length) {
  avgReply.forEach(function (r) { lines.push('- ' + r.category + ': ' + fmtInterval(r.avg_reply)); });
} else {
  lines.push('- داده‌ای موجود نیست.');
}
lines.push('');
lines.push('تعداد تیکت‌های باز: ' + openCount);
lines.push('');
lines.push('۵ سؤال پرتکرار بدون پاسخ:');
if (topUnanswered.length) {
  topUnanswered.forEach(function (r) { lines.push('- ' + r.text + ' (' + r.freq + ' بار)'); });
} else {
  lines.push('- موردی ثبت نشده است.');
}

return [{ json: { chat_id: adminRows[0].json.telegram_chat_id, text: lines.join('\n') } }];
